window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3a5b22dfe3232227"]={"versions": [{"id": "FIG-3a5b22dfe3232227", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Kontext des AUTOSAR Generic Structure Template (Software-Architektur). Das Diagramm illustriert das Konzept wiederverwendbarer Schnittstellen (<code>PortInterface</code>) durch mehrere Softwarekomponenten-Typen (<code>ApplicationComponentType</code>) und Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>WindowControllerType</code>: «ApplicationComponentType» mit dem Port <code>ctrl</code> (rot umrandetes Port-Symbol am unteren Rand).\n</li><li><code>MainControllerType</code>: «ApplicationComponentType» mit zwei Ports am unteren Rand: <code>leftCtrl</code> und <code>rightCtrl</code>.\n</li><li><code>ControlInterface</code>: «interface», fungiert als gemeinsame Schnittstellendefinition.\n</li><li>Beziehungen: Gestrichelte gerichtete Abhängigkeitspfeile (Dependency) führen von den Ports <code>ctrl</code>, <code>leftCtrl</code> und <code>rightCtrl</code> jeweils auf die Schnittstelle <code>ControlInterface</code>. Die Kästen weisen jeweils ein oberes Namensfach und ein unteres Fach auf, getrennt durch eine horizontale Binnenlinie.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdarstellung. Die Pfeile modellieren die typisierende Zuordnung der Ports zu der gemeinsamen Schnittstelle <code>ControlInterface</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Demonstriert die Wiederverwendbarkeit von Schnittstellen (<code>PortInterface</code>) über Komponentengrenzen hinweg sowie die mehrfache Verwendung derselben Schnittstelle an mehreren Ports eines einzelnen Komponententyps (<code>leftCtrl</code>, <code>rightCtrl</code>). Bei der Modellierung im AUTOSAR-Metamodell referenziert jeder Port (<code>PortPrototype</code>) seine Schnittstellendefinition unabhängig davon, ob es sich um denselben oder unterschiedliche Komponententypen handelt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f59a66d5edcd3577", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Kontext des AUTOSAR Generic Structure Template (Software-Architektur). Das Diagramm illustriert das Konzept wiederverwendbarer Schnittstellen (<code>PortInterface</code>) durch mehrere Softwarekomponenten-Typen (<code>ApplicationComponentType</code>) und Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>WindowControllerType</code>: «ApplicationComponentType» mit dem Port <code>ctrl</code> (rot umrandetes Port-Symbol am unteren Rand).\n</li><li><code>MainControllerType</code>: «ApplicationComponentType» mit zwei Ports am unteren Rand: <code>leftCtrl</code> und <code>rightCtrl</code>.\n</li><li><code>ControlInterface</code>: «interface», fungiert als gemeinsame Schnittstellendefinition.\n</li><li>Beziehungen: Gestrichelte gerichtete Abhängigkeitspfeile (Dependency) führen von den Ports <code>ctrl</code>, <code>leftCtrl</code> und <code>rightCtrl</code> jeweils auf die Schnittstelle <code>ControlInterface</code>. Die Kästen weisen jeweils ein oberes Namensfach und ein unteres Fach auf, getrennt durch eine horizontale Binnenlinie.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdarstellung. Die Pfeile modellieren die typisierende Zuordnung der Ports zu der gemeinsamen Schnittstelle <code>ControlInterface</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Demonstriert die Wiederverwendbarkeit von Schnittstellen (<code>PortInterface</code>) über Komponentengrenzen hinweg sowie die mehrfache Verwendung derselben Schnittstelle an mehreren Ports eines einzelnen Komponententyps (<code>leftCtrl</code>, <code>rightCtrl</code>). Bei der Modellierung im AUTOSAR-Metamodell referenziert jeder Port (<code>PortPrototype</code>) seine Schnittstellendefinition unabhängig davon, ob es sich um denselben oder unterschiedliche Komponententypen handelt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0e489e741ae29263", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Kontext des AUTOSAR Generic Structure Template (Software-Architektur). Das Diagramm illustriert das Konzept wiederverwendbarer Schnittstellen (<code>PortInterface</code>) durch mehrere Softwarekomponenten-Typen (<code>ApplicationComponentType</code>) und Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>WindowControllerType</code>: «ApplicationComponentType» mit dem Port <code>ctrl</code> (rot umrandetes Port-Symbol am unteren Rand).\n</li><li><code>MainControllerType</code>: «ApplicationComponentType» mit zwei Ports am unteren Rand: <code>leftCtrl</code> und <code>rightCtrl</code>.\n</li><li><code>ControlInterface</code>: «interface», fungiert als gemeinsame Schnittstellendefinition.\n</li><li>Beziehungen: Gestrichelte gerichtete Abhängigkeitspfeile (Dependency) führen von den Ports <code>ctrl</code>, <code>leftCtrl</code> und <code>rightCtrl</code> jeweils auf die Schnittstelle <code>ControlInterface</code>. Die Kästen weisen jeweils ein oberes Namensfach und ein unteres Fach auf, getrennt durch eine horizontale Binnenlinie.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdarstellung. Die Pfeile modellieren die typisierende Zuordnung der Ports zu der gemeinsamen Schnittstelle <code>ControlInterface</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Demonstriert die Wiederverwendbarkeit von Schnittstellen (<code>PortInterface</code>) über Komponentengrenzen hinweg sowie die mehrfache Verwendung derselben Schnittstelle an mehreren Ports eines einzelnen Komponententyps (<code>leftCtrl</code>, <code>rightCtrl</code>). Bei der Modellierung im AUTOSAR-Metamodell referenziert jeder Port (<code>PortPrototype</code>) seine Schnittstellendefinition unabhängig davon, ob es sich um denselben oder unterschiedliche Komponententypen handelt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b24146df4a1339df", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Kontext des AUTOSAR Generic Structure Template (Software-Architektur). Das Diagramm illustriert das Konzept wiederverwendbarer Schnittstellen (<code>PortInterface</code>) durch mehrere Softwarekomponenten-Typen (<code>ApplicationComponentType</code>) und Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>WindowControllerType</code>: «ApplicationComponentType» mit dem Port <code>ctrl</code> (rot umrandetes Port-Symbol am unteren Rand, Beschriftung <code>ctrl</code> unterhalb des Ports platziert).\n</li><li><code>MainControllerType</code>: «ApplicationComponentType» mit zwei Ports am unteren Rand: <code>leftCtrl</code> und <code>rightCtrl</code> (Beschriftungen oberhalb der jeweiligen Ports platziert).\n</li><li><code>ControlInterface</code>: «interface», fungiert als gemeinsame Schnittstellendefinition.\n</li><li>Beziehungen: Gestrichelte gerichtete Abhängigkeitspfeile führen von den Ports <code>ctrl</code>, <code>leftCtrl</code> und <code>rightCtrl</code> jeweils auf die Schnittstelle <code>ControlInterface</code>. Die Kästen der Komponenten und der Schnittstelle sind als einteilige Rechtecke ohne horizontale Binnentrennlinie ausgeführt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdarstellung. Die Pfeile modellieren die typisierende Zuordnung der Ports zu der gemeinsamen Schnittstelle <code>ControlInterface</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Demonstriert die Wiederverwendbarkeit von Schnittstellen (<code>PortInterface</code>) über Komponentengrenzen hinweg sowie die mehrfache Verwendung derselben Schnittstelle an mehreren Ports eines einzelnen Komponententyps (<code>leftCtrl</code>, <code>rightCtrl</code>). Bei der Modellierung im AUTOSAR-Metamodell referenziert jeder Port (<code>PortPrototype</code>) seine Schnittstellendefinition unabhängig davon, ob es sich um denselben oder unterschiedliche Komponententypen handelt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3a5b22dfe3232227", "to": "FIG-f59a66d5edcd3577", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f59a66d5edcd3577", "to": "FIG-0e489e741ae29263", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0e489e741ae29263", "to": "FIG-b24146df4a1339df", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Klassen- und Schnittstellenkästen (<code>WindowControllerType</code>, <code>MainControllerType</code>, <code>ControlInterface</code>): Horizontale Trennlinien zwischen Namensfach und Inhaltsfach entfernt.\n</li><li>Port-Beschriftung <code>ctrl</code>: Von oberhalb des Ports (im Kasteninneren) nach unterhalb des Ports (außerhalb des Kastens) verschoben.\n</li></ul>"}]};
